/// A `--test-repo` value as a path target: no trailing slash, and a
/// `./` on what would otherwise read as a bare name or `owner/name`.
fn test_repo_path(p: &str) -> String {
    let p = p.trim_end_matches('/');
    let is_path = p.starts_with(['/', '~', '$'])
        || p.starts_with("./")
        || p.starts_with("../")
        || p == "."
        || p == "..";
    if is_path {
        p.to_string()
    } else {
        format!("./{p}")
    }
}

impl From<&InitArgs> for InitParams {
    /// Convert clap-derived `InitArgs` into the flat `InitParams`.
    ///
    /// Production path: sets `create_symlink: true`. Tests that
    /// need `create_symlink: false` construct `InitParams`
    /// directly (or post-edit the field).
    fn from(a: &InitArgs) -> Self {
        // `--test-repo` is a path `--target` with local remotes beside it.
        let test_repo = a.test_repo.as_deref().map(test_repo_path);
        let repo = match &test_repo {
            Some(p) => Some(RepoSelector {
                category: "local".to_string(),
                value: Some(format!("{p}.remotes")),
            }),
            None => a.repo.value.clone(),
        };
        let target = test_repo.or_else(|| a.target.clone());
        Self {
            // OK: clap requires --target unless --test-repo or the retired
            // positionals were given, and `to_params` refuses those first
            target: target.unwrap_or_default(),
            name: a.name.clone(),
            account: a.account.value.clone(),

