}

/// Two test repos side by side are whole workspaces, each pushed to
/// its own remotes, which `init` creates though no parent exists yet.
#[test]
fn test_repos_share_a_directory() {
    let base = tmp_root("test-repos");
    let ctx = Context::load().expect("load user config");
    for name in ["one", "two"] {
        let mut args = args_for("unused");
        args.target = None;
        args.provision.dry_run.value = false;
        args.test_repo = Some(base.join(name).to_string_lossy().into_owned());
        let mut params = InitParams::from(&args);
        params.create_symlink = false;
        init(&ctx, &params).expect("init --test-repo");

        let remotes = base.join(format!("{name}.remotes"));
        for bare in ["remote-work.git", "remote-work.agent-session.git"] {
            assert!(
                remotes.join(bare).join("packed-refs").exists()
                    || remotes.join(bare).join("refs/heads/main").exists(),
                "{name}: {bare} holds main"
            );
        }
        let config = std::fs::read_to_string(base.join(name).join(".git/config")).unwrap();
        assert!(
            config.contains(&format!("{name}.remotes/remote-work.git")),
            "{name}: {config}"
        );
    }
    let _ = std::fs::remove_dir_all(&base);
}

/// `--target` needs no value with `--test-repo`, and a plain init's
/// params keep their symlink.
#[test]
fn the_test_repo_flag_stands_in_for_the_target() {
    let cli = Cli::try_parse_from(["vc-x1", "init", "--test-repo", "./tmp/one"]).unwrap();
    let Some(Commands::Init(args)) = cli.command else {
        panic!("expected init");
    };
    assert_eq!(args.test_repo.as_deref(), Some("./tmp/one"));
    assert!(Cli::try_parse_from(["vc-x1", "init"]).is_err());
    assert!(InitParams::from(&args_for("./tmp/one")).create_symlink);
}

/// What names a remote, another target, an existing directory, or a
/// publish is refused with `--test-repo`, and so is a URL.
#[test]
fn a_test_repo_refuses_what_it_cannot_mean() {
    use crate::subcommand::SubcommandRunner;

    let test_repo = |set: fn(&mut InitArgs)| {
        let mut args = args_for("unused");
        args.target = None;
        args.test_repo = Some("./tmp/one".to_string());
        set(&mut args);
        args.to_params().err()
    };
    assert!(test_repo(|_| {}).is_none());
    for (flag, set) in [
        (
            "--target",
            (|a| a.target = Some("./x".into())) as fn(&mut InitArgs),
        ),
        ("--name", |a| a.name = Some("x".into())),
        ("--account", |a| a.account.value = Some("x".into())),
        ("--repo", |a| {
            a.repo.value = Some(RepoSelector {
                category: "local".into(),
                value: Some("/t".into()),
            })
        }),
        ("--adopt", |a| a.adopt = true),
        ("--private", |a| a.provision.private.value = true),
    ] {
        let err = test_repo(set).expect(flag);
        assert!(err.starts_with(flag), "{flag}: {err}");
    }
    let url = test_repo(|a| a.test_repo = Some("https://github.com/o/n".into())).unwrap();
    assert!(url.contains("is a URL"), "{url}");
}

