python3 - <<'EOF'
p = "src/init/params.rs"
s = open(p).read()
old_doc = """/// - `repo`: `--repo` value parsed into a `RepoSelector`.
"""
new_doc = """/// - `repo`: `--repo` value parsed into a `RepoSelector`.
/// - `test_remotes`: `--test-repo`, the directory its bare remotes,
///   named by the repo, go in, in place of the `--repo` chain.
"""
assert s.count(old_doc) == 1; s = s.replace(old_doc, new_doc)
old_f = """    pub repo: Option<RepoSelector>,
    pub por: bool,"""
new_f = """    pub repo: Option<RepoSelector>,
    pub test_remotes: Option<String>,
    pub por: bool,"""
assert s.count(old_f) == 1; s = s.replace(old_f, new_f)
start = s.index("/// A `--test-repo` value as a path target")
end = s.index("impl From<&InitArgs> for InitParams {")
s = s[:start] + s[end:]
old_body = """        // `--test-repo` is a path `--target` with local remotes beside it.
        let test_repo = a.test_repo.as_deref().map(test_repo_path);
        let repo = match &test_repo {
            Some(p) => Some(RepoSelector {
                category: "local".to_string(),
                value: Some(format!("{p}.remotes")),
            }),
            None => a.repo.value.clone(),
        };
        let target = test_repo.or_else(|| a.target.clone());
        Self {
            // OK: clap requires --target unless --test-repo or the retired
            // positionals were given, and `to_params` refuses those first
            target: target.unwrap_or_default(),
            name: a.name.clone(),
            account: a.account.value.clone(),
            repo,
"""
new_body = """        Self {
            // OK: clap requires --target unless the retired positionals
            // were given, and `to_params` refuses those first
            target: a.target.clone().unwrap_or_default(),
            name: a.name.clone(),
            account: a.account.value.clone(),
            repo: a.repo.value.clone(),
            test_remotes: a.test_repo.clone(),
"""
assert s.count(old_body) == 1; s = s.replace(old_body, new_body)
open(p, "w").write(s)
EOF

