            continue;
        }
        if RESERVED_TEMPLATE_ENTRIES.contains(&name_str.as_ref()) {
            return Err(format!(
                "--use-template: {label} template '{}' contains reserved entry '{}'",
                p.display(),
                name_str
            )
            .into());
        }
    }
    Ok(())
}

