271	/// Top-level non-hidden files init writes. Kept here so that if init is
272	/// ever extended to write non-hidden top-level files, the pre-flight
273	/// conflict scan flags any template that would clash. Currently empty
274	/// because init only writes hidden files (`.vc-config.md`, `.gitignore`),
275	/// and the template copy skips hidden entries.
276	const RESERVED_TEMPLATE_ENTRIES: &[&str] = &[];
