278	/// Validate one template directory: exists, is a directory, and has no
279	/// top-level non-hidden entry that would collide with init's own writes.
280	///
281	/// - `label` prefixes every error message (`work` / `agent`).
282	pub(crate) fn validate_template_one(
283	    label: &str,
284	    p: &Path,
285	) -> Result<(), Box<dyn std::error::Error>> {
286	    if !p.exists() {
287	        return Err(format!(
288	            "--use-template: {label} template '{}' does not exist",
289	            p.display()
290	        )
291	        .into());
292	    }
293	    if !p.is_dir() {
294	        return Err(format!(
295	            "--use-template: {label} template '{}' is not a directory",
296	            p.display()
297	        )
298	        .into());
299	    }
300	    for entry in std::fs::read_dir(p)? {
301	        let entry = entry?;
302	        let name = entry.file_name();
303	        let name_str = name.to_string_lossy();
304	        if name_str.starts_with('.') {
305	            continue;
306	        }
307	        if RESERVED_TEMPLATE_ENTRIES.contains(&name_str.as_ref()) {
308	            return Err(format!(
309	                "--use-template: {label} template '{}' contains reserved entry '{}'",
310	                p.display(),
311	                name_str
312	            )
313	            .into());
314	        }
315	    }
316	    Ok(())
317	}
