330	/// Recursively copy non-hidden entries from `src` to `dst`. Any entry whose
331	/// file name starts with `.` is skipped. Symlinks are skipped with a debug
332	/// log: templates don't need them, and following them risks escaping the
333	/// template tree.
334	pub(crate) fn copy_template_recursive(
335	    src: &Path,
336	    dst: &Path,
337	) -> Result<(), Box<dyn std::error::Error>> {
338	    for entry in std::fs::read_dir(src)? {
339	        let entry = entry?;
340	        let name = entry.file_name();
341	        let name_str = name.to_string_lossy();
342	        if name_str.starts_with('.') {
343	            continue;
344	        }
345	        let src_path = entry.path();
346	        let dst_path = dst.join(&name);
347	        let ft = entry.file_type()?;
348	        if ft.is_symlink() {
349	            debug!("skip symlink {}", src_path.display());
350	            continue;
351	        }
352	        if ft.is_dir() {
353	            mkdir_p(&dst_path)?;
354	            copy_template_recursive(&src_path, &dst_path)?;
355	        } else if ft.is_file() {
356	            debug!("copy {} -> {}", src_path.display(), dst_path.display());
357	            std::fs::copy(&src_path, &dst_path)?;
358	        }
359	    }
360	    Ok(())
361	}
