363	/// Replace the first line of `<dir>/README.md` with `# <name>`. If
364	/// `README.md` is absent, this is a no-op. Trailing content after the
365	/// first newline is preserved verbatim, and a file with no newline becomes
366	/// just `# <name>`.
367	pub(crate) fn rewrite_readme_first_line(
368	    dir: &Path,
369	    name: &str,
370	) -> Result<(), Box<dyn std::error::Error>> {
371	    let readme = dir.join("README.md");
372	    if !readme.exists() {
373	        return Ok(());
374	    }
375	    let content = std::fs::read_to_string(&readme)?;
376	    let rest = match content.find('\n') {
377	        Some(pos) => &content[pos..],
378	        None => "",
379	    };
380	    let new_content = format!("# {name}{rest}");
381	    std::fs::write(&readme, new_content)?;
382	    debug!("rewrote first line of {}", readme.display());
383	    Ok(())
384	}
