    }
    write_por_gitignore(&plan.project_dir)?;
    steps.begin(Step::CommitWork);
    let work_chid = commit_initial(
        &plan.project_dir,
        "work",
        INITIAL_TITLE,
        OchidStrategy::None,
    )?;
