    let hash = jj::cid_of(&plan.project_dir, "@-")?;
    debug!("work repo: chid={work_chid} hash={hash}");

    steps.begin(Step::PublishWork);
    let work_chid_final = push_repo(
        &plan.project_dir,
        "work",
        plan,
        params,
        visibility,
        &plan.work_url,
        plan.gh_work_slug.as_deref(),
        plan.work_bare_path.as_deref(),
