470	) -> Result<AgentResolution, Box<dyn std::error::Error>> {
471	    let (ws, repo) = common::load_repo(work_root)?;
472	    let partner = partner::partners(&arrival.commit, (&ws, &repo), tolerance_secs)?;
473	    let commits: Vec<Commit> = match &partner {
474	        Partner::Linked(commits) => commits.clone(),
475	        Partner::Candidates { commits, .. } => commits.first().cloned().into_iter().collect(),
476	    };
477	    let entry = crate::transcript::parse_str(&arrival.text)
478	        .entries
479	        .into_iter()
480	        .next();
481	    let mut windows = Vec::new();
482	    for c in commits {
483	        let changed = work_window::changed_files(&repo, &c)?;
484	        let narrowed = entry
485	            .as_ref()
486	            .map(|e| work_window::written_files(e, &changed))
487	            .unwrap_or_default(); // OK: an unparsed line is discussion
488	        let only = (!narrowed.is_empty()).then_some(narrowed.as_slice());
489	        let hunks = work_window::hunks_of(&repo, &c, only)?;
490	        windows.push((c, narrowed, hunks));
491	    }
492	    Ok(AgentResolution { partner, windows })
493	}
