495	/// Print each work window: whether the line wrote a file, then every
496	/// region as `FILE:START-END` with its removed and added lines.
497	fn print_work_windows(r: &AgentResolution) {
498	    for (commit, narrowed, hunks) in &r.windows {
499	        if narrowed.is_empty() {
500	            info!("discussion, so {}'s whole diff", short_chid(commit));
501	        } else {
502	            let files: Vec<String> = narrowed.iter().map(|f| f.display().to_string()).collect();
503	            info!("write   {} in {}", files.join(", "), short_chid(commit));
504	        }
505	        for h in hunks {
506	            let end = h.start + h.len.saturating_sub(1);
507	            if h.len == 0 {
508	                info!(
509	                    "window  {}:{} (removed before it)",
510	                    h.file.display(),
511	                    h.start
