/// first, the order `jj log --reversed` lists them.
pub fn cids_of(repo: &Path, revset: &str) -> Result<Vec<String>> {
    let mut ids: Vec<String> = commits_of(repo, revset)?
        .iter()
        .map(|c| c.id().hex())
        .collect();
    ids.reverse();
    Ok(ids)
}

